create table accounts (active bit not null, otp_attempts int not null, points int not null, token_version int not null, verified bit not null, id bigint identity not null, otp_expires datetime2(6), otp_sent datetime2(6), store_id bigint, version bigint not null, email varchar(160) not null, name varchar(255) not null, otp_hash varchar(255), otp_purpose varchar(255), password_hash varchar(255), phone varchar(255), roles varchar(255), primary key (id));
create table addresses (default_address bit not null, id bigint identity not null, user_id bigint, version bigint not null, detail varchar(500), label varchar(255), phone varchar(255), recipient varchar(255), primary key (id));
create table audit_records (actor_id bigint, created_at datetime2(6), id bigint identity not null, version bigint not null, detail varchar(2000), action varchar(255), primary key (id));
create table cart_lines (quantity int not null, id bigint identity not null, product_id bigint, store_id bigint, user_id bigint, version bigint not null, ingredient_ids varchar(2000), note varchar(300), primary key (id));
create table categories (id bigint identity not null, version bigint not null, name varchar(255), slug varchar(255), primary key (id));
create table catering_requests (people int not null, quoted_total numeric(38,2), id bigint identity not null, store_id bigint, user_id bigint, version bigint not null, address varchar(255), contact_name varchar(255), event_at varchar(255), note varchar(255), package_name varchar(255), phone varchar(255), status varchar(255), primary key (id));
create table group_lines (quantity int not null, group_id bigint, id bigint identity not null, product_id bigint, user_id bigint, version bigint not null, ingredient_ids varchar(255), member_name varchar(255), primary key (id));
create table group_meals (created_at datetime2(6), id bigint identity not null, organizer_id bigint, store_id bigint, version bigint not null, code varchar(255), status varchar(255), title varchar(255), primary key (id));
create table ingredients (available bit not null, calories int not null, price numeric(38,2), id bigint identity not null, version bigint not null, allergens varchar(255), group_name varchar(255), name varchar(255), primary key (id));
create table meal_orders (commission_rate numeric(38,2), delivery_fee numeric(38,2), discount numeric(38,2), points_awarded bit not null, subtotal numeric(38,2), total numeric(38,2), created_at datetime2(6), id bigint identity not null, payment_expires datetime2(6), shipper_id bigint, store_id bigint, updated_at datetime2(6), user_id bigint, version bigint not null, address varchar(1500), note varchar(1500), checkout_key varchar(255), code varchar(255), contact_name varchar(255), group_code varchar(255), payment_method varchar(255), payment_status varchar(255), phone varchar(255), scheduled_at varchar(255), status varchar(255), transaction_ref varchar(255), type varchar(255), voucher_code varchar(255), primary key (id));
create table media_records (created_at datetime2(6), id bigint identity not null, user_id bigint, version bigint not null, kind varchar(255), public_id varchar(255), url varchar(255), primary key (id));
create table notices (seen bit not null, created_at datetime2(6), id bigint identity not null, order_id bigint, user_id bigint, version bigint not null, text varchar(255), primary key (id));
create table order_events (actor_id bigint, created_at datetime2(6), id bigint identity not null, order_id bigint, version bigint not null, description varchar(255), status varchar(255), primary key (id));
create table order_lines (calories int not null, quantity int not null, unit_price numeric(38,2), id bigint identity not null, order_id bigint, product_id bigint, version bigint not null, customization varchar(2000), image varchar(255), name varchar(255), primary key (id));
create table products (available bit not null, calories int not null, customizable bit not null, price numeric(38,2), stock int not null, created_at datetime2(6), id bigint identity not null, store_id bigint, version bigint not null, category varchar(255), description varchar(255), image varchar(255), name varchar(255), primary key (id));
create table refund_requests (amount numeric(38,2), created_at datetime2(6), id bigint identity not null, order_id bigint, store_id bigint, user_id bigint, version bigint not null, reason varchar(2000), evidence varchar(255), reply varchar(255), status varchar(255), primary key (id));
create table reviews (stars int not null, created_at datetime2(6), id bigint identity not null, order_line_id bigint, product_id bigint, user_id bigint, version bigint not null, media varchar(2000), text varchar(3000), author varchar(255), primary key (id));
create table reward_logs (points int not null, created_at datetime2(6), id bigint identity not null, user_id bigint, version bigint not null, description varchar(255), primary key (id));
create table settings (id bigint identity not null, version bigint not null, name varchar(255), setting_value varchar(255), primary key (id));
create table shop_applications (id bigint identity not null, user_id bigint, version bigint not null, address varchar(255), name varchar(255), phone varchar(255), reply varchar(255), status varchar(255), primary key (id));
create table stores (active bit not null, commission numeric(38,2), delivery bit not null, delivery_fee numeric(38,2), latitude float(53) not null, longitude float(53) not null, pickup bit not null, id bigint identity not null, owner_id bigint, version bigint not null, address varchar(255), hours varchar(255), name varchar(255), phone varchar(255), primary key (id));
create table user_marks (created_at datetime2(6), id bigint identity not null, product_id bigint, user_id bigint, version bigint not null, kind varchar(255), primary key (id));
create table vouchers (active bit not null, discount_value numeric(38,2), max_discount numeric(38,2), minimum numeric(38,2), usage_limit int not null, used int not null, ends_at datetime2(6), id bigint identity not null, starts_at datetime2(6), store_id bigint, user_id bigint, version bigint not null, code varchar(255), name varchar(255), type varchar(255), primary key (id));
